SET LOCAL search_path = pg_catalog;

CREATE TABLE ctrlz.node_dns_state (
  node_id     uuid PRIMARY KEY REFERENCES ctrlz.nodes (id) ON DELETE CASCADE,
  f3_unmet    text[] NOT NULL DEFAULT '{}'
    CHECK (f3_unmet <@ ARRAY['hub_fit', 'peer_view', 'stable_period', 'flapping', 'held']::text[]
           AND pg_catalog.cardinality(f3_unmet) <= 5),
  f3_due_at   timestamptz,
  drain_state text NOT NULL DEFAULT 'none' CHECK (drain_state IN ('none', 'draining', 'done')),
  drain_since timestamptz,
  updated_at  timestamptz NOT NULL DEFAULT pg_catalog.now(),
  CONSTRAINT node_dns_state_drain_since CHECK ((drain_state = 'none') = (drain_since IS NULL))
);
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON ctrlz.node_dns_state
  FOR EACH ROW EXECUTE FUNCTION ctrlz.touch_updated_at();

GRANT SELECT, INSERT (node_id, f3_unmet, f3_due_at, drain_state, drain_since),
  UPDATE (f3_unmet, f3_due_at, drain_state, drain_since) ON ctrlz.node_dns_state TO ctrlz_hub;
GRANT SELECT ON ctrlz.node_dns_state TO ctrlz_admin;
